DROP TABLE IF EXISTS `sys_business_action`;
CREATE TABLE `sys_business_action` (
  `id` varchar(30) NOT NULL DEFAULT '',
  `perm_id` varchar(30) DEFAULT NULL COMMENT '权限ID',
  `action_value` varchar(80) DEFAULT NULL,
  `action_ignore_user_scope` tinyint(1) DEFAULT '0' COMMENT '是否忽略用户权限范围',
  `action_ignore_group_scope` tinyint(1) DEFAULT '0' COMMENT '是否忽略组织用户权限',
  `action_ignore_company_scope_tags` text COMMENT '忽略分公司权限范围的用户属性',
  `action_only_filter_company_tags` text COMMENT '只过滤分公司的用户属性',
  `connect_value` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `connect_ignore_user_scope_tags` text COMMENT '忽略用户权限范围的用户属性',
  `connect_ignore_group_scope_tags` text COMMENT '忽略组织权限范围的用户属性',
  `connect_be_always_filter_create_user_column` tinyint(1) DEFAULT '1' COMMENT '总是过滤创建用户列',
  `connect_user_auth_column` text COMMENT '用户权限列',
  `connect_group_auth_column` text COMMENT '组织权限列',
  `connect_table_name_with_auth_inject` varchar(50) DEFAULT NULL COMMENT '权限注入表名位置',
  `connect_table_name_with_column_inject` varchar(50) DEFAULT NULL COMMENT '列权限注入表名位置',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `create_user` varchar(20) DEFAULT NULL COMMENT '创建人',
  `update_user` varchar(20) DEFAULT NULL COMMENT '更新人',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_user_cn_name` varchar(50) DEFAULT NULL COMMENT '创建人姓名',
  `update_user_cn_name` varchar(50) DEFAULT NULL COMMENT '更新人姓名',
  `be_lock` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否锁定',
  `state` varchar(20) DEFAULT 'ACTIVE' COMMENT '状态',
  `note` varchar(255) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `sys_business_perm`;
CREATE TABLE `sys_business_perm` (
  `id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '主键ID',
  `menu_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '菜单ID',
  `button_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '功能按钮ID',
  `perm_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '权限名称',
  `perm_action` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '权限动作(标记)',
  `req_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '请求URL',
  `req_method` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT 'GET' COMMENT '请求方法',
  `note` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '备注',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `create_user` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '创建人',
  `update_user` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '更新人',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_user_cn_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '创建人姓名',
  `update_user_cn_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '更新人姓名',
  `action_alias` varchar(500) DEFAULT NULL COMMENT '动作别名,多个以逗号间隔',
  `action_ref` varchar(50) DEFAULT NULL COMMENT '引用Action',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `INDEX_URL_METHOD` (`req_url`,`req_method`) USING BTREE,
  KEY `INDEX_ACTION` (`perm_action`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='系统-业务权限定义';

