  `create_user` varchar(20) DEFAULT NULL COMMENT '创建人',
  `update_user` varchar(20) DEFAULT NULL COMMENT '更新人',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_user_cn_name` varchar(50) DEFAULT NULL COMMENT '创建人姓名',
  `update_user_cn_name` varchar(50) DEFAULT NULL COMMENT '更新人姓名',
  `be_copy_origin` tinyint(1) DEFAULT NULL COMMENT '是否复制',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `sys_role`;
CREATE TABLE `sys_role` (
  `id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT 'id',
  `role_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '角色名称',
  `note` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '备注',
  `state` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT 'ACTIVE' COMMENT '状态',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `create_user` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '创建人',
  `update_user` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '更新时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新人',
  `group_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '组织ID',
  `be_super` tinyint(1) DEFAULT '0' COMMENT '是否超级管理员',
  `create_user_cn_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '创建人姓名',
  `update_user_cn_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '更新人姓名',
  `be_lock` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否锁定',
  `be_default` tinyint(1) DEFAULT '0' COMMENT '是否默认角色',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='系统-角色定义';

DROP TABLE IF EXISTS `sys_role_resource`;
CREATE TABLE `sys_role_resource` (
  `id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '角色资源关系id',
  `resource_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '资源id',
  `role_id` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '角色id',
  `resource_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '资源类型',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_user` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '创建人',
  `update_user` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '更新人',
  `create_user_cn_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '创建人姓名',
  `update_user_cn_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '更新人姓名',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `UNIQUE` (`resource_id`,`role_id`,`resource_type`) USING BTREE,
  KEY `INDEX_ROLE` (`role_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='系统-角色-资源关系';

DROP TABLE IF EXISTS `sys_rule`;
CREATE TABLE `sys_rule` (
  `id` varchar(30) NOT NULL DEFAULT '',
  `rule_name` varchar(30) DEFAULT NULL,
  `state` varchar(30) DEFAULT NULL,
  `execute_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '执行方式',
  `rule_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '规则分类',
  `advice` varchar(30) DEFAULT 'NONE' COMMENT '执行切入点',
  `group_id` varchar(20) DEFAULT NULL COMMENT '组织ID',
  `create_user` varchar(20) DEFAULT NULL COMMENT '创建人',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_user` varchar(20) DEFAULT NULL COMMENT '更新人',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_user_cn_name` varchar(50) DEFAULT NULL COMMENT '创建人姓名',
  `update_user_cn_name` varchar(50) DEFAULT NULL COMMENT '更新人姓名',
  `rule_version` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '版本号',
  `note` varchar(250) DEFAULT NULL,
  `bind_variable` varchar(30) DEFAULT NULL COMMENT '绑定变量',
  `be_combine_arg` tinyint(1) DEFAULT '1' COMMENT '是否绑定参数',
  `return_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT 'LIST' COMMENT '返回类型',
  `event_tag` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '事件标识',
  `event_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT 'ADVICE' COMMENT '事件类型(切点和规则标识)',
  `be_lock` tinyint(1) DEFAULT '0' COMMENT '是否锁定',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `sys_rule_detail`;
CREATE TABLE `sys_rule_detail` (
  `id` varchar(30) NOT NULL DEFAULT '',
  `be_menu` tinyint(1) DEFAULT '0' COMMENT '是否菜单',
  `menu_index` varchar(30) DEFAULT NULL,
  `be_folder` tinyint(1) DEFAULT NULL COMMENT '是否文件夹',
  `can_move` tinyint(1) DEFAULT NULL COMMENT '是否能移动',
  `menu_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '类型',
  `children` text COMMENT '子节点',
  `can_rename` tinyint(1) DEFAULT '0' COMMENT '是否重命名',
  `data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '数据信息',
  `express` text COMMENT '表达式',
  `rule_id` varchar(30) DEFAULT NULL COMMENT '规则管理',
  `group_id` varchar(20) DEFAULT NULL COMMENT '组织ID',
  `create_user` varchar(20) DEFAULT NULL COMMENT '创建人',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_user` varchar(20) DEFAULT NULL COMMENT '更新人',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_user_cn_name` varchar(50) DEFAULT NULL COMMENT '创建人姓名',
  `update_user_cn_name` varchar(50) DEFAULT NULL COMMENT '更新人姓名',
  `line_number` int DEFAULT NULL COMMENT '行数',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `sys_rule_function`;
CREATE TABLE `sys_rule_function` (
  `id` varchar(30) NOT NULL DEFAULT '',
  `title` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '名称',
  `function_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '调用方式',
  `return_type` varchar(200) DEFAULT NULL COMMENT '返回类型',
  `note` text COMMENT '描述',
  `be_lock` tinyint(1) DEFAULT '0' COMMENT '是否锁定',
  `group_id` varchar(20) DEFAULT NULL COMMENT '组织ID',
  `create_user` varchar(20) DEFAULT NULL COMMENT '创建人',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_user` varchar(20) DEFAULT NULL COMMENT '更新人',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_user_cn_name` varchar(50) DEFAULT NULL COMMENT '创建人姓名',
  `update_user_cn_name` varchar(50) DEFAULT NULL COMMENT '更新人姓名',
  `priority` int DEFAULT NULL COMMENT '顺序',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `sys_rule_menu`;
CREATE TABLE `sys_rule_menu` (
  `id` varchar(30) NOT NULL DEFAULT '',
  `menu_index` varchar(30) DEFAULT NULL,
  `be_folder` tinyint(1) DEFAULT NULL COMMENT '是否文件夹',
  `can_move` tinyint(1) DEFAULT NULL COMMENT '是否能移动',
  `children` text COMMENT '子节点',
  `menu_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '类型',
  `can_rename` tinyint(1) DEFAULT '0' COMMENT '是否重命名',
  `title` varchar(30) DEFAULT NULL COMMENT '主题',
  `description` varchar(200) DEFAULT NULL COMMENT '描述',
  `icon` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '图标',
  `express` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '默认表达式',
  `be_menu` tinyint(1) DEFAULT '1' COMMENT '是否菜单',
  `group_id` varchar(20) DEFAULT NULL COMMENT '组织ID',
  `create_user` varchar(20) DEFAULT NULL COMMENT '创建人',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_user` varchar(20) DEFAULT NULL COMMENT '更新人',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_user_cn_name` varchar(50) DEFAULT NULL COMMENT '创建人姓名',
  `update_user_cn_name` varchar(50) DEFAULT NULL COMMENT '更新人姓名',
  `be_used` tinyint(1) DEFAULT '1' COMMENT '是否启用',
  `priority` int DEFAULT NULL COMMENT '顺序',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `sys_tenant`;
CREATE TABLE `sys_tenant` (
  `id` varchar(30) NOT NULL DEFAULT '',
  `simple_name` varchar(30) DEFAULT NULL COMMENT '简称',
  `name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `note` varchar(255) DEFAULT NULL COMMENT '备注',
  `state` varchar(20) DEFAULT 'ACTIVE' COMMENT '状态',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `create_user` varchar(20) DEFAULT NULL COMMENT '创建人',
  `update_user` varchar(20) DEFAULT NULL COMMENT '更新时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新人',
  `create_user_cn_name` varchar(50) DEFAULT NULL COMMENT '创建人姓名',
  `update_user_cn_name` varchar(50) DEFAULT NULL COMMENT '更新人姓名',
  `root` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '顶级组织T开头+4位',
  `business_id` varchar(30) DEFAULT NULL COMMENT '业务ID',
  `be_search` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否可以被搜索',
  `tenant_rank` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT 'ONE' COMMENT '等级',
  `score` bigint DEFAULT '0' COMMENT '积分',
  `tax_no` varchar(30) DEFAULT NULL COMMENT '税号',
  `address` varchar(300) DEFAULT NULL COMMENT '地址',
  `phone` varchar(30) DEFAULT NULL COMMENT '电话',
  `cer_url` varchar(300) DEFAULT NULL COMMENT '证书文件地址',
  `balance` decimal(12,2) DEFAULT '0.00' COMMENT '余额',
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_root` (`root`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `sys_tenant_button`;
CREATE TABLE `sys_tenant_button` (
  `id` varchar(30) NOT NULL DEFAULT '',
  `tenant_id` varchar(30) DEFAULT NULL COMMENT '菜单ID',
  `button_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '按钮ID',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `create_user` varchar(20) DEFAULT NULL COMMENT '创建人',
  `update_user` varchar(20) DEFAULT NULL COMMENT '更新时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新人',
  `create_user_cn_name` varchar(50) DEFAULT NULL COMMENT '创建人姓名',
  `update_user_cn_name` varchar(50) DEFAULT NULL COMMENT '更新人姓名',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `sys_tenant_fee`;
CREATE TABLE `sys_tenant_fee` (
  `id` varchar(30) NOT NULL DEFAULT '',
  `exchange_name` varchar(50) DEFAULT NULL COMMENT '传输名称',
  `exchange_time` timestamp NULL DEFAULT NULL COMMENT '传输时间',
  `state` varchar(30) DEFAULT NULL COMMENT '传输状态',
  `ip_address` varchar(55) DEFAULT NULL COMMENT 'IP地址',
  `create_user_cn_name` varchar(50) DEFAULT NULL COMMENT '创建人姓名',
  `update_user_cn_name` varchar(50) DEFAULT NULL COMMENT '更新人姓名',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `create_user` varchar(20) DEFAULT NULL COMMENT '创建人',
  `update_user` varchar(20) DEFAULT NULL COMMENT '更新人',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `os` varchar(100) DEFAULT NULL COMMENT '操作系统+版本',
  `tenant_id` varchar(30) DEFAULT NULL,
  `unit_price` decimal(12,2) DEFAULT NULL COMMENT '单价',
  `total_price` decimal(12,2) DEFAULT NULL COMMENT '总价',
  `request_qty` int DEFAULT NULL COMMENT '请求数量',
  `fee_type` varchar(30) DEFAULT NULL COMMENT '计价方式(按量/包月)',
  `exchange_url` varchar(500) DEFAULT NULL COMMENT '传输地址',
  `exchange_method` varchar(30) DEFAULT NULL COMMENT '传输方法',
  `function_id` varchar(30) DEFAULT NULL COMMENT '功能ID',
  `browser` varchar(100) DEFAULT NULL,
  `group_id` varchar(20) DEFAULT NULL COMMENT '组织ID',
  `after_money` decimal(12,2) DEFAULT NULL COMMENT '操作后金额',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `sys_tenant_function`;
CREATE TABLE `sys_tenant_function` (
  `id` varchar(30) NOT NULL DEFAULT '',
  `tenant_id` varchar(30) DEFAULT NULL COMMENT '租户ID',
  `function_id` varchar(30) DEFAULT NULL,
  `create_user_cn_name` varchar(50) DEFAULT NULL COMMENT '创建人姓名',
  `update_user_cn_name` varchar(50) DEFAULT NULL COMMENT '更新人姓名',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `create_user` varchar(20) DEFAULT NULL COMMENT '创建人',
  `update_user` varchar(20) DEFAULT NULL COMMENT '更新人',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `function_name` varchar(50) DEFAULT NULL COMMENT '功能名称',
  `group_id` varchar(20) DEFAULT NULL COMMENT '组织ID',
  `expire_time` timestamp NULL DEFAULT NULL COMMENT '过期时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `sys_tenant_group`;
CREATE TABLE `sys_tenant_group` (
  `id` varchar(30) NOT NULL DEFAULT '',
  `grht` int DEFAULT NULL COMMENT '右节点',
  `glft` int DEFAULT NULL COMMENT '左节点',
  `group_name` varchar(50) DEFAULT NULL COMMENT '组织名称',
  `parent_id` varchar(20) DEFAULT NULL COMMENT '父组织ID',
  `group_level` int DEFAULT NULL COMMENT '组织层级',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `create_user` varchar(20) DEFAULT NULL COMMENT '创建人',
  `update_user` varchar(20) DEFAULT NULL COMMENT '更新人',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_user_cn_name` varchar(50) DEFAULT NULL COMMENT '创建人姓名',
  `update_user_cn_name` varchar(50) DEFAULT NULL COMMENT '更新人姓名',
  `tenant_id` varchar(30) DEFAULT NULL COMMENT '租户ID',
  `be_root` tinyint(1) DEFAULT '0' COMMENT '是否根节点',
  `group_id` varchar(20) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

