  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `sys_tenant_position_role`;
CREATE TABLE `sys_tenant_position_role` (
  `id` varchar(30) NOT NULL DEFAULT '',
  `tenant_id` varchar(30) NOT NULL COMMENT '租户ID',
  `role_id` varchar(20) DEFAULT NULL COMMENT '角色ID',
  `position_id` varchar(20) DEFAULT NULL COMMENT '职位ID',
